using Npgsql;using SanSo.Worker;using Xunit;
namespace SanSo.Worker.Tests;
public sealed class PostgresOutboxRuntimeTests
{
 [Fact]public async Task ConcurrentClaimLeaseRecoveryAndFailClosedDeadLetterWorkAgainstPostgres(){var cs=Environment.GetEnvironmentVariable("SANSO_RUNTIME_POSTGRES");if(string.IsNullOrWhiteSpace(cs))return;var tenantA=Guid.NewGuid();var tenantB=Guid.NewGuid();await Organizations(cs,tenantA,tenantB);var claimId=Guid.NewGuid();var leaseId=Guid.NewGuid();var failId=Guid.NewGuid();await Seed(cs,claimId,tenantA,"NOOP_AUDIT","PENDING",DateTimeOffset.UtcNow.AddMinutes(-3));await Seed(cs,leaseId,tenantA,"NOOP_AUDIT","PROCESSING",DateTimeOffset.UtcNow.AddMinutes(-2));await Seed(cs,failId,tenantB,"SHOPEE_SYNC","PENDING",DateTimeOffset.UtcNow.AddMinutes(-1));await using var source=NpgsqlDataSource.Create(cs);var first=new PostgresOutboxStore(source,tenantA.ToString());var second=new PostgresOutboxStore(source,tenantA.ToString());var claims=await Task.WhenAll(first.Claim(TimeSpan.FromMinutes(2),default),second.Claim(TimeSpan.FromMinutes(2),default));Assert.Single(claims.Where(x=>x?.Id==claimId));var claimed=claims.Single(x=>x is not null);await first.Complete(claimed!.Id,default);Assert.Equal(1,await first.RecoverExpiredLeases(default));Assert.Equal("RETRY_SCHEDULED",await Status(cs,leaseId));var processor=new OutboxProcessor(new PostgresOutboxStore(source,tenantB.ToString()),new PilotOutboxHandler());Assert.True(await processor.Tick());var(status,error)=await State(cs,failId);Assert.Equal("DEAD_LETTER",status);Assert.Equal("PARTNER_ADAPTER_NOT_CONFIGURED",error);}
 static async Task Organizations(string cs,params Guid[] ids){await using var c=new NpgsqlConnection(cs);await c.OpenAsync();foreach(var id in ids){await using var q=c.CreateCommand();q.CommandText="INSERT INTO organizations(id,slug,name) VALUES($1,$2,'Worker V1 isolated test')";q.Parameters.AddWithValue(id);q.Parameters.AddWithValue($"worker-v1-{id:N}");await q.ExecuteNonQueryAsync();}}static async Task Seed(string cs,Guid id,Guid tenant,string type,string status,DateTimeOffset due){await using var c=new NpgsqlConnection(cs);await c.OpenAsync();await using var q=c.CreateCommand();q.CommandText="INSERT INTO outbox_messages(id,organization_id,type,payload,correlation_id,attempt,next_attempt_at,status,created_at) VALUES($1,$2::uuid,$3,'{}'::jsonb,$4,0,$5,$6,$5)";q.Parameters.AddWithValue(id);q.Parameters.AddWithValue(tenant);q.Parameters.AddWithValue(type);q.Parameters.AddWithValue($"test-{id:N}");q.Parameters.AddWithValue(due);q.Parameters.AddWithValue(status);await q.ExecuteNonQueryAsync();}static async Task<string> Status(string cs,Guid id)=>(await State(cs,id)).Status;static async Task<(string Status,string? Error)> State(string cs,Guid id){await using var c=new NpgsqlConnection(cs);await c.OpenAsync();await using var q=c.CreateCommand();q.CommandText="SELECT status,error_code FROM outbox_messages WHERE id=$1";q.Parameters.AddWithValue(id);await using var r=await q.ExecuteReaderAsync();Assert.True(await r.ReadAsync());return(r.GetString(0),r.IsDBNull(1)?null:r.GetString(1));}
}
